  'deity.effect.GoddessOfMirage': '전원에게 마법 공격 배율 {magicalAttackMultiplier}배, 물리 방어 배율 1.10배.',
  'deity.effect.GodOfResonance': '전원의 공명을 1+α단계 강화. 공명은 마법 공격뿐 아니라 원거리 공격에도 적용. 마법 방어 배율 1.10배, HP {hpMultiplier}배.',
